SELECT CASE WHEN o.amount >= 1360 THEN 'high' WHEN o.amount >= 520 THEN 'mid' ELSE 'low' END AS amount_bucket, ROUND(STDDEV(oi.unit_price), 2) AS stddev_unit_price, ROUND(AVG(oi.quantity), 2) AS avg_quantity FROM order_items oi LEFT JOIN orders o ON oi.order_id = o.id LEFT JOIN customers c ON o.customer_id = c.id WHERE oi.unit_price BETWEEN 170 AND 330 GROUP BY CASE WHEN o.amount >= 1360 THEN 'high' WHEN o.amount >= 520 THEN 'mid' ELSE 'low' END ORDER BY amount_bucket, avg_quantity DESC
